(async () => {
  await new Promise(resolve => document.addEventListener('DOMContentLoaded', resolve, {once: true}));
  const report = message => fetch('/test/result', {method: 'POST', body: message});
  const assert = (check, message) => { if (!check) throw new Error(message); };
  const mapURL = 'https://maps.example/?pin=hall&zoom=16';
  const wait = async check => {
    const deadline = Date.now() + 12000;
    while (!check()) {
      if (Date.now() > deadline) throw new Error('Timed out: ' + check);
      await new Promise(resolve => setTimeout(resolve, 25));
    }
  };
  try {
    if (sessionStorage.getItem('event-saved')) {
      await wait(() => document.querySelector('.event-component'));
      const event = document.querySelector('.event-component');
      const dates = [...event.querySelectorAll('time')].map(time => time.dateTime);
      assert(dates.join(' ') === '2027-01-12T18:30:00-06:00 2027-01-12T20:00:00-06:00', 'Published times must use the chosen time zone and date.');
      const venue = event.querySelector('.event-location');
      const [map, details] = event.querySelectorAll('.event-links .event-link');
      assert(venue.textContent === 'Community hall' && details.href === 'https://example.com/talk', 'Readers need the location and details link.');
      assert(map.href === mapURL && map.textContent === 'View map', 'Readers need a link to the saved map.');
      assert(map.target === '_blank' && map.relList.contains('noopener'), 'View map must open in a new tab.');
      const mapBox = map.getBoundingClientRect();
      const mapGap = mapBox.top - venue.getBoundingClientRect().bottom;
      assert(mapGap >= 0 && mapGap <= 11 && mapBox.height >= 36 && mapBox.height < details.getBoundingClientRect().height, 'View map must be a compact button close below the venue.');
      const image = event.querySelector('.event-image img');
      await wait(() => image?.naturalWidth > 0);
      assert(image.alt === 'The observatory at night', 'The saved image and description must appear on the public card.');
      const imageLink = image.closest('a');
      assert(imageLink?.href === image.src && !imageLink.target, 'The image must link directly to the uncropped image as a fallback.');
      assert(imageLink.getAttribute('aria-label').includes(image.alt) && imageLink.querySelector('.event-image-hint').getBoundingClientRect().width > 0, 'The image link must retain its description and show an expand icon.');
      const imageBox = image.getBoundingClientRect();
      const contentBox = event.querySelector('.event-content').getBoundingClientRect();
      if (innerWidth < 768) {
        const cardBox = event.getBoundingClientRect();
        assert(Math.abs(imageBox.width - cardBox.width + 2) <= 1 && imageBox.height <= 260 && getComputedStyle(image).objectFit === 'cover', 'A stacked image must fill the width of the card and stay within the banner height.');
        assert(imageBox.bottom <= contentBox.top, 'A stacked image must sit above the event details.');
      } else {
        assert(imageBox.left >= contentBox.right && getComputedStyle(image).objectFit === 'contain', 'A wide card must show the image within its side panel.');
      }
      assert(document.documentElement.scrollWidth <= innerWidth + 1, 'The event card must fit the viewport.');
      imageLink.focus();
      const imageScroll = scrollY;
      imageLink.click();
      const viewer = document.querySelector('.album-viewer');
      const fullImage = viewer?.querySelector('[data-album-image]');
      await wait(() => viewer?.matches(':modal') && fullImage?.naturalWidth > 0);
      const collapse = viewer.querySelector('[data-album-close]');
      assert(fullImage.src === imageLink.href && fullImage.alt === image.alt && getComputedStyle(fullImage).objectFit === 'contain', 'The viewer must show the uncropped image and preserve its description.');
      assert(getComputedStyle(fullImage).cursor === 'pointer', 'The cursor must indicate that the enlarged image can be clicked to dismiss it.');
      const collapseIcon = collapse.querySelector('path');
      assert(collapse === document.activeElement && collapse.getAttribute('aria-label') === 'Collapse image' && collapseIcon.getAttribute('d') === collapseIcon.dataset.collapsePath, 'The image viewer must focus a visible collapse button with the collapse icon.');
      assert([...viewer.querySelectorAll('nav, [data-album-prev], [data-album-next], [data-album-captions], [data-album-thumbnails]')].every(control => control.hidden), 'An event image must hide album controls.');
      const point = viewer.querySelector('.album-viewer-image-frame').getBoundingClientRect();
      const viewerBox = viewer.getBoundingClientRect();
      const collapseBox = collapse.getBoundingClientRect();
      assert(viewerBox.width === innerWidth && viewerBox.height === innerHeight, 'The event image viewer must cover the viewport.');
      assert(viewer.querySelector('header').hidden && point.top === viewerBox.top, 'The image must use the space above it without a top toolbar.');
      assert(collapseBox.top >= point.bottom && viewerBox.bottom - collapseBox.bottom <= 16 && viewerBox.right - collapseBox.right <= 16 && collapseBox.width >= 44 && collapseBox.height >= 44, 'The collapse button must be reachable at the lower right, below the image.');
      const pointer = (target, type, id, offset = 0, pointerType = 'touch') => {
        target.dispatchEvent(new PointerEvent(type, {pointerType, pointerId: id, button: 0, clientX: point.x + point.width / 2 + offset, clientY: point.y + point.height / 2, bubbles: true}));
      };
      pointer(fullImage, 'pointerdown', 1, 0, 'mouse');
      pointer(fullImage, 'pointerup', 1, 0, 'mouse');
      assert(viewer.open, 'The viewer must stay open through pointer release so the click reaches it.');
      fullImage.click();
      await wait(() => !viewer.isConnected);
      assert(document.activeElement === imageLink && scrollY === imageScroll, 'Clicking the image must close the viewer and restore focus and scroll position.');
      imageLink.click();
      const reopened = document.querySelector('.album-viewer');
      const zoom = reopened.querySelector('[data-album-zoom]');
      await wait(() => !zoom.disabled);
      const zoomIn = zoom.querySelector('[data-album-zoom-in]');
      assert(zoom.getAttribute('aria-label') === 'Zoom in' && !zoom.hasAttribute('aria-pressed') && getComputedStyle(zoomIn).display !== 'none', 'Zoom in must be an action button with a plus icon.');
      const zoomedImage = reopened.querySelector('[data-album-image]');
      pointer(zoomedImage, 'pointerdown', 2, -30);
      pointer(zoomedImage, 'pointerdown', 3, 30);
      pointer(zoomedImage, 'pointermove', 3, 80);
      pointer(zoomedImage, 'pointerup', 3, 80);
      pointer(zoomedImage, 'pointerup', 2, -30);
      assert(reopened.open && zoom.getAttribute('aria-label') === 'Reset zoom' && getComputedStyle(zoomIn).display === 'none', 'Pinching must zoom without closing the viewer and switch the button to a minus icon.');
      assert(getComputedStyle(zoomedImage).cursor === 'grab', 'The cursor must indicate that a zoomed image can be dragged.');
      pointer(zoomedImage, 'pointerdown', 4);
      pointer(zoomedImage, 'pointermove', 4, 50);
      pointer(zoomedImage, 'pointermove', 4);
      pointer(zoomedImage, 'pointerup', 4);
      zoomedImage.click();
      assert(reopened.open, 'Dragging the zoomed image must keep the viewer open, even when the drag ends where it started.');
      reopened.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true, cancelable: true}));
      await wait(() => !reopened.isConnected);
      assert(document.activeElement === imageLink, 'Escape must close the image even when zoomed.');
      imageLink.click();
      const expanded = document.querySelector('.album-viewer');
      expanded.querySelector('[data-album-close]').click();
      await wait(() => !expanded.isConnected);
      assert(document.activeElement === imageLink && scrollY === imageScroll, 'The collapse button must return to the image in the post.');
      const edit = document.querySelector('a[href^="/post/update/"]');
      await htmx.ajax('GET', edit.getAttribute('href'), {target: '#article-content', swap: 'innerHTML'});
      await wait(() => document.querySelector('[data-event-editor] textarea[name=event]')?.hidden);
      const editor = document.querySelector('[data-event-editor]');
      assert(editor.querySelector('#event-zone').value === 'America/Chicago' && editor.querySelector('#event-end-time').value === '20:00' && !editor.querySelector('#event-all-day').checked && editor.querySelector('[data-component-unsaved]').hidden, 'Reopening must preserve the event without marking it unsaved.');
      assert(!editor.querySelector('[data-image-preview]').hidden && editor.querySelector('#event-image-alt').value === image.alt, 'Reopening must show the saved image and description.');
      assert(editor.querySelector('#event-map-url').value === mapURL, 'Reopening must preserve the saved map link.');
      const [startDate, endDate, startTime, endTime] = ['#event-start-date', '#event-end-date', '#event-start-time', '#event-end-time']
        .map(selector => editor.querySelector(selector).getBoundingClientRect());
      const allDay = editor.querySelector('.event-all-day').getBoundingClientRect();
      assert(Math.max(startDate.bottom, endDate.bottom) <= allDay.top && allDay.bottom <= Math.min(startTime.top, endTime.top), 'All day must sit between the date and time fields.');
      if (innerWidth > 479) {
        assert(startDate.top === endDate.top && startTime.top === endTime.top, 'Dates and times must each share a row.');
      } else {
        assert(startDate.top < endDate.top && startTime.top < endTime.top, 'On narrow screens, the dates and then the times must stack in start-to-end order.');
      }
      const layout = () => {
        const top = editor.getBoundingClientRect().top;
        return [editor, ...editor.querySelectorAll('.event-date-fields > div, #event-location')].map(element => {
          const {x, y, width, height} = element.getBoundingClientRect();
          return [x, y - top, width, height];
        });
      };
      const savedLayout = JSON.stringify(layout());
      editor.querySelector('#event-all-day').click();
      assert(!editor.querySelector('[data-component-unsaved]').hidden && JSON.stringify(layout()) === savedLayout, 'Changing a saved event to All day must keep the same layout as the unsaved indicator appears.');
      await report('PASS');
      return;
    }
    await wait(() => document.querySelector('#post-form .CodeMirror') && document.querySelector('[name=event]').hidden);
    const form = document.querySelector('#post-form');
    const editor = form.querySelector('[data-event-editor]');
    form.elements.title.value = 'Event review';
    form.elements.slug.value = 'event-review';
    form.querySelector('[data-component-picker] summary').click();
    form.querySelector('[data-component-add=event]').click();
    assert(!editor.hidden && document.activeElement === editor.querySelector('#event-title'), 'Adding an event must focus its name.');
    const set = (field, value) => {
      const input = editor.querySelector(`[data-event-field="${field}"]`);
      input.value = value;
      input.dispatchEvent(new Event('input', {bubbles: true}));
    };
    set('title', 'Evening talk');
    set('startDate', '2027-01-12');
    const allDay = editor.querySelector('#event-all-day');
    const zone = editor.querySelector('#event-zone-change');
    const startTime = editor.querySelector('#event-start-time');
    const endTime = editor.querySelector('#event-end-time');
    assert(!allDay.checked && !zone.disabled && startTime.required, 'New events start in timed mode.');
    set('startTime', '18:30');
    assert(JSON.parse(form.elements.event.value).timeZone === 'America/Denver', 'A new event must use the site time zone.');
    allDay.click();
    const allDayEvent = JSON.parse(form.elements.event.value);
    assert(allDayEvent.allDay && !allDayEvent.startTime && !allDayEvent.timeZone && [startTime, endTime, zone].every(field => field.disabled && field.getBoundingClientRect().height > 0), 'All day must disable and omit times and the time zone while keeping the controls in view.');
    allDay.click();
    assert(JSON.parse(form.elements.event.value).startTime === '18:30' && [startTime, endTime, zone].every(field => !field.disabled), 'Switching back to timed mode must restore the controls and time.');
    const original = form.elements.event.value;
    const panel = editor.querySelector('#event-zone-picker');
    const locationTop = editor.querySelector('#event-location').offsetTop;
    zone.click();
    const search = editor.querySelector('#event-zone-search');
    assert(!panel.hidden && document.activeElement === search && editor.querySelector('#event-location').offsetTop === locationTop, 'Opening the inline picker must focus search without moving the fields below it.');
    assert(document.documentElement.scrollWidth <= innerWidth + 1, 'The inline picker must fit the viewport.');
    assert([...editor.querySelectorAll('[data-event-zone-results] button')].map(button => button.value).join() === 'UTC', 'Opening the picker should offer only the relevant defaults before searching.');
    search.value = 'not a city';
    search.dispatchEvent(new Event('input', {bubbles: true}));
    assert(!editor.querySelector('[data-event-zone-empty]').hidden, 'An unmatched query must explain why the list is empty.');
    zone.click();
    assert(panel.hidden && document.activeElement === zone && form.elements.event.value === original, 'Cancel must leave the selected zone intact and restore focus.');
    zone.click();
    search.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true, cancelable: true}));
    assert(panel.hidden && document.activeElement === zone, 'Escape must close the picker and restore focus.');
    zone.click();
    search.value = 'chicago';
    search.dispatchEvent(new Event('input', {bubbles: true}));
    assert(editor.querySelector('[data-event-zone-results] button')?.value === 'America/Chicago', 'Searching a city must show its zone.');
    search.dispatchEvent(new KeyboardEvent('keydown', {key: 'Enter', bubbles: true, cancelable: true}));
    assert(panel.hidden && JSON.parse(form.elements.event.value).timeZone === 'America/Chicago' && editor.querySelector('#event-zone-name').textContent.includes('Chicago'), 'Enter must select and show the matching zone.');
    set('mapURL', mapURL);
    const venueInput = editor.querySelector('#event-location');
    assert(venueInput.required && venueInput.labels[0].textContent.includes('(required)'), 'Adding a map link must show that the venue is required.');
    form.requestSubmit();
    await wait(() => document.activeElement === venueInput && venueInput.getAttribute('aria-invalid') === 'true');
    set('location', 'Community hall');
    assert(!venueInput.hasAttribute('aria-invalid'), 'Typing a venue must clear the required-field error.');
    set('url', 'https://example.com/talk');
    set('endDate', '2027-01-12');
    assert(endTime.required && endTime.labels[0].textContent.includes('(required)'), 'An end date must show that the end time is required.');
    form.requestSubmit();
    await wait(() => document.activeElement === endTime && endTime.getAttribute('aria-invalid') === 'true');
    set('endDate', '');
    assert(!endTime.required && !endTime.hasAttribute('aria-invalid'), 'Clearing the end date must make the time optional and clear its error.');
    set('endTime', '18:00');
    form.requestSubmit();
    await wait(() => editor.querySelector('[data-component-error]:not([hidden])')?.textContent.includes('after the start time'));
    assert(document.activeElement === endTime && endTime.getAttribute('aria-invalid') === 'true' && endTime.value === '18:00', 'A rejected end time must stay editable and receive focus and an error.');
    set('endTime', '20:00');
    const canvas = document.createElement('canvas');
    canvas.width = 32; canvas.height = 24;
    canvas.getContext('2d').fillRect(0, 0, 16, 24);
    const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
    const upload = editor.querySelector('input[type=file]');
    const uploadImage = (blob, name) => {
      const transfer = new DataTransfer();
      transfer.items.add(new File([blob], name, {type: 'image/png'}));
      upload.files = transfer.files;
      upload.dispatchEvent(new Event('change', {bubbles: true}));
    };
    uploadImage(blob, 'Observatory.png');
    allDay.click();
    await wait(() => !form.dataset.uploading && JSON.parse(form.elements.event.value).imageID);
    assert(zone.disabled, 'Finishing an upload must keep the time zone disabled for an all-day event.');
    allDay.click();
    editor.querySelector('[data-image-reset]').click();
    assert(!JSON.parse(form.elements.event.value).imageID && editor.querySelector('[data-image-preview]').hidden, 'Clear must remove the event image.');
    const chooseImage = async () => {
      editor.querySelector('[data-media-browse]').click();
      await wait(() => document.querySelector('.media-browser [data-media-select]'));
      document.querySelector('.media-browser [data-media-select]').click();
      await wait(() => !document.querySelector('.media-browser') && JSON.parse(form.elements.event.value).imageID);
    };
    await chooseImage();
    set('imageAlt', 'The first image description');
    const previousImage = JSON.parse(form.elements.event.value).imageID;
    await chooseImage();
    assert(JSON.parse(form.elements.event.value).imageID === previousImage && editor.querySelector('#event-image-alt').value === 'The first image description', 'Re-selecting the same image must preserve its description.');
    canvas.getContext('2d').fillRect(16, 0, 16, 24);
    const replacement = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
    uploadImage(replacement, 'Different observatory photo.png');
    await wait(() => !form.dataset.uploading && JSON.parse(form.elements.event.value).imageID !== previousImage);
    assert(!editor.querySelector('#event-image-alt').value && !JSON.parse(form.elements.event.value).imageAlt, 'Replacing a photo must clear its previous description.');
    set('imageAlt', 'The observatory at night');
    const saved = form.elements.event.value;
    allDay.click();
    editor.querySelector('[data-component-remove]').click();
    form.querySelector('[data-component-undo=event]').click();
    assert(allDay.checked, 'Undo must restore the saved All day setting.');
    allDay.click();
    assert(form.elements.event.value === saved && editor.querySelector('#event-zone').value === 'America/Chicago', 'Undo must also restore the disabled times and time zone.');
    assert(document.documentElement.scrollWidth <= innerWidth + 1, 'Event fields must fit the viewport.');
    form.querySelector('[name=published][value=on]').checked = true;
    sessionStorage.setItem('event-saved', 'true');
    form.requestSubmit();
  } catch (error) { await report(error.stack || String(error)); }
})();
